def harmony_label(harmony: str) -> dict[str, str]:
    """Return the human-readable name of a colour relationship."""

    return dict(HARMONY_LABELS.get(harmony, {"zh": harmony, "en": harmony}))


# The one entry whose accent is a live tenant input rather than a curated
# design decision — see `studio_theme()`/`free_accent` in palette.py.
FREE_ACCENT_STYLE_ID = "custom"


def style_theme(style_id: str, scheme: str = "light", accent_hue: float | None = None) -> dict:
    """Return one style's flat token map for a given light/dark scheme.

    Falls back to the style's only available mode when the requested one does
    not exist, and to the default style when the id is unknown, so a stale
    tenant setting can never render an empty theme.

    `accent_hue` is honoured ONLY for `FREE_ACCENT_STYLE_ID` — that is the
    studio's one colour knob, solved rather than read from a literal, so a
    neon logo becomes a deep pine rather than a button nobody can read. For
    any of the eight curated themes the hue is part of the design and an
    `accent_hue` argument is ignored: the literal below is the whole point of
    a curated theme staying put.
    """

    preset = VISUAL_STYLE_PRESETS.get(style_id) or VISUAL_STYLE_PRESETS[DEFAULT_STYLE_ID]
    resolved_id = style_id if style_id in VISUAL_STYLE_PRESETS else DEFAULT_STYLE_ID
    themes = preset["themes"]
    mode = scheme if scheme in themes else preset["modes"][0]
    shape = {
        "style_id": resolved_id,
        "theme_mode": "preset",
        **STYLE_SHAPE.get(resolved_id, STYLE_SHAPE[DEFAULT_STYLE_ID]),
    }
    if accent_hue is None or resolved_id != FREE_ACCENT_STYLE_ID:
        return {**shape, **themes[mode]}
    solved = palette.build(palette.studio_theme(float(accent_hue)), mode == "dark")
    return {**shape, "accent_hue": round(float(accent_hue) % 360, 1), **solved}


def accent_hue_of_colour(value: str) -> float:
    """The hue this product will actually use for a studio-supplied colour."""

    return palette.accent_hue_from(value)


